"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 6 (P1 v0.4, sections 4.4-4.5, 5.5): source positions for the timeline renderer.

The simulated RIRs of RIRS_NOISES list no source positions, so each RIR's source distance is estimated from its
direct-path delay (first sample above 10% of the peak, times 343 m/s) and its direct-to-reverberant ratio (2.5 ms
around the direct path vs the rest). Positions are relative to each room's own distances (small rooms are small):
near = the closest 20% of the room's RIRs, across = the 40th-80th percentile, door = the farthest 10%. Footsteps
walking away use RIRs of increasing distance. Writes results/step0_v04/rir_positions.json.
usage: python -I scripts/step0v4_rir_positions.py
"""
import json
import os

import numpy as np
import soundfile as sf

ROOT = "data/rirs_x/RIRS_NOISES/simulated_rirs"


def main():
    out = {}
    for size in ("smallroom", "mediumroom"):
        for room in sorted(os.listdir(os.path.join(ROOT, size))):
            d = os.path.join(ROOT, size, room)
            if not os.path.isdir(d):
                continue
            rows = []
            for f in sorted(os.listdir(d)):
                x, sr = sf.read(os.path.join(d, f), dtype="float32")
                a = np.abs(x)
                first = int(np.nonzero(a > 0.1 * a.max())[0][0])
                e = x.astype(np.float64) ** 2
                w = int(0.0025 * sr)
                drr = 10 * np.log10(e[max(0, first - w):first + w].sum() / (e[first + w:].sum() + 1e-12))
                rows.append((f"{d}/{f}".replace("\\", "/"), round(first / sr * 343, 3), round(float(drr), 2)))
            rows.sort(key=lambda r: r[1])
            n = len(rows)
            key = f"{'small' if size == 'smallroom' else 'medium'}-{room}"
            out[key] = {"max_dist_m": rows[-1][1],
                        "near": [r[0] for r in rows[:max(1, int(0.2 * n))]],
                        "across": [r[0] for r in rows[int(0.4 * n):int(0.8 * n)]],
                        "door": [r[0] for r in rows[int(0.9 * n):]],
                        "by_distance": rows}
    json.dump(out, open("results/step0_v04/rir_positions.json", "w", encoding="utf-8"))
    md = np.array([v["max_dist_m"] for v in out.values()])
    print(f"rooms {len(out)}; farthest source per room: median {np.median(md):.2f} m, 10% {np.quantile(md, 0.1):.2f}, "
          f"90% {np.quantile(md, 0.9):.2f}")


if __name__ == "__main__":
    main()
